-- ===================================================================
-- HEME — Block 1 of 2: schema, row level security, triggers
--
-- Paste into the Supabase SQL Editor and run. Safe on a fresh project.
-- Run Block 2 (02_seed.sql) afterwards.
--
-- Creates 21 enums, 17 tables, their indexes and foreign keys, then the
-- isolation layer: helper functions, the signup trigger, the tenancy
-- inheritance triggers, and RLS policies on every table.
--
-- Isolation model: an organisation is the tenant boundary; inside it a coach
-- sees only rows they own (athletes, groups, programs carry owner_coach_id).
-- Everything else inherits visibility through one denormalised column, so no
-- policy walks more than one join.
-- ===================================================================

begin;

-- pgcrypto backs gen_random_uuid() and the bcrypt hashing used in Block 2.
create extension if not exists pgcrypto with schema extensions;

-- ===================================================================
-- 1. Tables, enums, indexes, foreign keys  (generated by drizzle-kit)
-- ===================================================================

CREATE TYPE "public"."assignment_status" AS ENUM('scheduled', 'active', 'completed', 'paused', 'cancelled');
CREATE TYPE "public"."athlete_status" AS ENUM('active', 'injured', 'rehab', 'inactive', 'archived');
CREATE TYPE "public"."block_structure" AS ENUM('straight', 'superset', 'triset', 'circuit', 'complex', 'contrast', 'emom', 'amrap', 'for_time', 'interval');
CREATE TYPE "public"."block_type" AS ENUM('accumulation', 'transmutation', 'realization', 'deload', 'taper', 'gpp', 'spp', 'in_season', 'off_season', 'pre_season', 'return_to_play');
CREATE TYPE "public"."contraction_emphasis" AS ENUM('concentric', 'eccentric', 'isometric', 'ballistic', 'mixed');
CREATE TYPE "public"."exercise_category" AS ENUM('main_lift', 'accessory', 'corrective', 'plyometric', 'conditioning', 'mobility', 'warmup', 'skill');
CREATE TYPE "public"."force_vector" AS ENUM('vertical', 'horizontal', 'lateral', 'rotational');
CREATE TYPE "public"."group_type" AS ENUM('team', 'squad', 'small_group', 'individual');
CREATE TYPE "public"."laterality" AS ENUM('bilateral', 'unilateral', 'alternating');
CREATE TYPE "public"."load_basis" AS ENUM('own_1rm', 'derived_from_exercise', 'bodyweight', 'absolute_only');
CREATE TYPE "public"."logged_session_status" AS ENUM('scheduled', 'in_progress', 'completed', 'partial', 'missed', 'skipped');
CREATE TYPE "public"."max_source" AS ENUM('tested', 'estimated', 'manual');
CREATE TYPE "public"."microcycle_load_type" AS ENUM('load', 'unload', 'deload', 'test');
CREATE TYPE "public"."movement_pattern" AS ENUM('squat', 'hinge', 'lunge', 'vertical_push', 'horizontal_push', 'vertical_pull', 'horizontal_pull', 'carry', 'rotation', 'anti_rotation', 'anti_extension', 'anti_lateral_flexion', 'gait', 'jump_land', 'throw', 'sprint', 'olympic', 'isolation', 'mobility');
CREATE TYPE "public"."percent_of" AS ENUM('1rm', 'training_max', 'bodyweight', 'e1rm');
CREATE TYPE "public"."periodization_model" AS ENUM('linear', 'block', 'undulating_daily', 'undulating_weekly', 'conjugate', 'concurrent', 'reverse_linear', 'autoregulated', 'none');
CREATE TYPE "public"."session_block_type" AS ENUM('warmup', 'activation', 'power', 'main_strength', 'accessory', 'conditioning', 'cooldown');
CREATE TYPE "public"."session_type" AS ENUM('strength', 'power', 'hypertrophy', 'conditioning', 'recovery', 'testing', 'skill', 'rest');
CREATE TYPE "public"."set_type" AS ENUM('warmup', 'ramp', 'working', 'top', 'backoff', 'drop', 'cluster', 'rest_pause', 'amrap', 'technique');
CREATE TYPE "public"."sex" AS ENUM('male', 'female', 'other');
CREATE TYPE "public"."user_role" AS ENUM('owner', 'coach', 'athlete');
CREATE TABLE "athletes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"owner_coach_id" uuid NOT NULL,
	"user_id" uuid,
	"first_name" text NOT NULL,
	"last_name" text NOT NULL,
	"email" text,
	"date_of_birth" date,
	"sex" "sex",
	"height_cm" double precision,
	"bodyweight_kg" double precision,
	"sport" text,
	"position" text,
	"status" "athlete_status" DEFAULT 'active' NOT NULL,
	"notes" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "group_members" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid DEFAULT null NOT NULL,
	"group_id" uuid NOT NULL,
	"athlete_id" uuid NOT NULL,
	"joined_at" date NOT NULL,
	"left_at" date
);

CREATE TABLE "groups" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"owner_coach_id" uuid NOT NULL,
	"name" text NOT NULL,
	"type" "group_type" DEFAULT 'team' NOT NULL,
	"sport" text,
	"season" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "organizations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"slug" text NOT NULL,
	"unit_system" text DEFAULT 'kg' NOT NULL,
	"plate_increment_kg" double precision DEFAULT 2.5 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "organizations_slug_unique" UNIQUE("slug")
);

CREATE TABLE "users" (
	"id" uuid PRIMARY KEY NOT NULL,
	"org_id" uuid NOT NULL,
	"email" text NOT NULL,
	"name" text NOT NULL,
	"role" "user_role" DEFAULT 'coach' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "exercises" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid,
	"name" text NOT NULL,
	"slug" text NOT NULL,
	"aliases" text[] DEFAULT '{}' NOT NULL,
	"description" text,
	"movement_pattern" "movement_pattern" NOT NULL,
	"category" "exercise_category" NOT NULL,
	"laterality" "laterality" DEFAULT 'bilateral' NOT NULL,
	"force_vector" "force_vector",
	"contraction_emphasis" "contraction_emphasis" DEFAULT 'mixed' NOT NULL,
	"equipment" text[] DEFAULT '{}' NOT NULL,
	"primary_muscles" text[] DEFAULT '{}' NOT NULL,
	"secondary_muscles" text[] DEFAULT '{}' NOT NULL,
	"tracked_metrics" text[] DEFAULT '{"load","reps"}' NOT NULL,
	"load_basis" "load_basis" DEFAULT 'absolute_only' NOT NULL,
	"derived_from_exercise_id" uuid,
	"derived_ratio" double precision,
	"is_max_testable" boolean DEFAULT false NOT NULL,
	"progression_of_id" uuid,
	"difficulty_level" integer DEFAULT 3 NOT NULL,
	"default_tempo" text,
	"default_rest_seconds" integer,
	"video_url" text,
	"thumbnail_url" text,
	"coaching_cues" text[] DEFAULT '{}' NOT NULL,
	"contraindications" text[] DEFAULT '{}' NOT NULL,
	"tags" text[] DEFAULT '{}' NOT NULL,
	"is_archived" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "exercise_slots" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
