CREATE INDEX "sessions_rls_idx" ON "sessions" USING btree ("org_id","program_id");
CREATE INDEX "athlete_maxes_athlete_idx" ON "athlete_maxes" USING btree ("athlete_id");
CREATE INDEX "athlete_maxes_lookup_idx" ON "athlete_maxes" USING btree ("athlete_id","exercise_id","tested_at");
CREATE INDEX "athlete_maxes_rls_idx" ON "athlete_maxes" USING btree ("org_id","athlete_id");
CREATE INDEX "logged_sessions_athlete_idx" ON "logged_sessions" USING btree ("athlete_id");
CREATE INDEX "logged_sessions_date_idx" ON "logged_sessions" USING btree ("date");
CREATE INDEX "logged_sessions_rls_idx" ON "logged_sessions" USING btree ("org_id","athlete_id");
